function __run336(t,i,press){/* pkgRUN ASK 336 (W2 7013, D1-D5; all four seats AGREE): an [L2] paragraph that names no verse reference of its own binds also to the run of [L1] paragraphs directly before it; [L3]/[L4]/headings end the run; it only adds verses the block quotes as [L1] */try{if(press)return [];const SEP=/\n[ \t]*\n/g;let ps=0,m;while((m=SEP.exec(t))&&m.index<i)ps=m.index+m[0].length;if(!/^[\s>*_#-]*$/.test(t.slice(ps,i)))return [];const rest=t.slice(i).search(/\n[ \t]*\n/);const para=t.slice(ps,rest<0?t.length:i+rest);if(refsIn(para).length)return [];const P=t.slice(0,ps).split(/\n[ \t]*\n/);let k=P.length-1;while(k>=0&&!P[k].trim())k--;const out=[];for(;k>=0;k--){const L=P[k].split('\n').filter(x=>x.trim());if(!L.length)break;const hd=x=>{const h=x.match(/^[\s>*_-]*\[L1\]\s*[*_]*\s*([^"“]{0,200})/);return h?refsIn(h[1]):null;};const r0=hd(L[0]);if(!r0||!r0.length)break;const got=[].concat(r0,...L.slice(1).map(x=>hd(x)||[]));out.unshift(...got);}return [...new Set(out)];}catch(e){return [];}}
